DOCUMENT();

#############
# Load Macros
#############

loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "PGlateximage.pl",
  "parserAssignment.pl",
  "parserOneOf.pl",
  "contextForm.pl",
  "contextFraction.pl",
  "ORCCA.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');

#######
# Setup
#######

$xmin = -1;
$xmax = 11;
$ymin = -50;
$ymax = 600;
Context("Fraction");
do {
  ($h,$x1) = random_subset(2,1..9);
  ($k,$y1) = random_subset(2,100..599);
  $m = Fraction(($y1 - $k)/($x1 - $h));
  $f = Formula("$m(x - $h) + $k")->reduce;
  $b = $f->eval(x => 0);
} until ($b != 0 && abs($h - $x1) >= 3);
$g = Formula("$m(x - $x1) + $y1")->reduce;
$xtop = ($ymax - $k)/$m + $h;
$xbot = ($ymin - $k)/$m + $h;
($start, $stop) = (num_sort($xmin,$xmax,$xtop,$xbot))[1,2];

package my::OneOf;
our @ISA = ('parser::OneOf');
sub cmp_compare {
  my ($self,$other,$ans) = @_;
  foreach $answer (@{$self->{data}}) {
    if ($answer->typeMatch($other)) {
      my $result = $answer->cmp->evaluate($other);
      if ($result->{score}) {
        $ans->score($result->{score});
        $ans->{ans_message} = $result->{ans_message};
        return $ans->{score};
      }
      if ($result->{ans_message}) {
        $ans->{ans_message} = $result->{ans_message}
          if !$ans->{ans_message} || length($ans->{ans_message}) > length($result->{ans_message});
      }
    }
  }
  return 0;
}
package main;
sub OneOfForm {my::OneOf->new(@_)}

Context("Form")->variables->add(y=>'Real');
parser::Assignment->Allow;
Context()->noreduce('(-x)+y','(-x)-y');
Context()->flags->set(reduceConstants => 0);
$eq = OneOfForm(Formula("y = $f"), Formula("y = $g"));
$leftright = ($m > 0) ? 'right' : 'left';

$image_1 = createLaTeXImage();
$image_1->addToPreamble(latexImagePreamble());
$image_1->BEGIN_LATEX_IMAGE
\begin{tikzpicture}
  \begin{axis}[
      xmin = $xmin,
      xmax = $xmax,
      ymin = $ymin,
      ymax = $ymax,
      xtick = {2,4,...,$xmax},
      minor xtick = {1,...,$xmax},
      ytick = {100,200,...,$ymax},
      minor ytick = {50,100,...,$ymax},
      width=0.33\orccaprintwidth,
      clip=false
    ]
    \addplot[firstcurve, domain=$start:$stop]{$f};
    \addplot[soliddot] coordinates {($h,$k)} node[below $leftright] {\(($h,$k)\)};
    \addplot[soliddot] coordinates {($x1,$y1)} node[below $leftright] {\(($x1,$y1)\)};
  \end{axis}
\end{tikzpicture}

END_LATEX_IMAGE

#############################
# Exercise Group Introduction
#############################

BEGIN_PGML
Determine a point-slope form line equation for the given line.

END_PGML

######
# Body
######

BEGIN_PGML
>> [@image(insertGraph($image_1), width=>600)@]*  <<

[_]{$eq}{16}

END_PGML

##########
# Solution
##########

BEGIN_PGML_SOLUTION
The slope is [`[$m]`] and the point [`([$h],[$k])`] is on the graph of this line, so one point-slope form equation for this line is [`y=[$f]\text{.}`]

END_PGML_SOLUTION

